INSERT INTO venues (id, name, slug, description, venue_type, address, neighborhood, latitude, longitude, price_range, website_url, genre_tags, accessibility_info) VALUES
  ('a1000000-0000-0000-0000-000000000001', 'Steppenwolf Theatre', 'steppenwolf', 'Founded in 1974 by Terry Kinney, Jeff Perry, and Gary Sinise. One of the most celebrated ensemble theaters in the world, known for raw, visceral storytelling.', 'institutional', '1650 N Halsted St', 'Lincoln Park', 41.9113, -87.6480, '$$$', 'https://steppenwolf.org', ARRAY['drama', 'new-work', 'ensemble'], 'Fully wheelchair accessible, assistive listening devices available'),
  ('a1000000-0000-0000-0000-000000000002', 'Neo-Futurists', 'neo-futurists', 'Home of Too Much Light Makes the Baby Go Blind — 30 plays in 60 minutes. Anarchic, audience-interactive, and proudly weird since 1988.', 'storefront', '5153 N Ashland Ave', 'Andersonville', 41.9756, -87.6690, '$', 'https://neofuturists.org', ARRAY['experimental', 'comedy', 'interactive'], 'Second floor venue, no elevator. Contact for accommodations'),
  ('a1000000-0000-0000-0000-000000000003', 'Lookingglass Theatre', 'lookingglass', 'Tony Award-winning company known for physically daring, visually stunning adaptations. Founded by Northwestern grads including David Schwimmer.', 'institutional', '821 N Michigan Ave', 'Magnificent Mile', 41.8977, -87.6243, '$$$', 'https://lookingglasstheatre.org', ARRAY['physical-theater', 'adaptation', 'spectacle'], 'Wheelchair accessible, audio description available'),
  ('a1000000-0000-0000-0000-000000000004', 'The Annoyance Theatre', 'annoyance', 'Birthplace of the Harold and home to some of Chicago''s most fearless comedy. If Second City is the establishment, Annoyance is the punk rock alternative.', 'storefront', '851 W Belmont Ave', 'Lakeview', 41.9397, -87.6524, '$', 'https://theannoyance.com', ARRAY['improv', 'comedy', 'musical'], 'Ground floor accessible'),
  ('a1000000-0000-0000-0000-000000000005', 'Court Theatre', 'court-theatre', 'The professional theater of the University of Chicago. Specializes in classic works reimagined through a modern lens — Shakespeare, Molière, Greek tragedy.', 'institutional', '5535 S Ellis Ave', 'Hyde Park', 41.7931, -87.6018, '$$', 'https://courttheatre.org', ARRAY['classic', 'drama', 'revival'], 'Fully wheelchair accessible, open captioning select performances'),
  ('a1000000-0000-0000-0000-000000000006', 'The Den Theatre', 'den-theatre', 'Multi-stage venue in Wicker Park hosting everything from storefront premieres to touring stand-up. Five stages under one roof.', 'storefront', '1331 N Milwaukee Ave', 'Wicker Park', 41.9065, -87.6722, '$$', 'https://thedentheatre.com', ARRAY['drama', 'comedy', 'new-work', 'stand-up'], 'Main stage accessible, upper stages have stairs'),
  ('a1000000-0000-0000-0000-000000000007', 'Victory Gardens Theater', 'victory-gardens', 'Dedicated to developing and producing new theater work. A launchpad for Chicago playwrights since 1974.', 'institutional', '2433 N Lincoln Ave', 'Lincoln Park', 41.9267, -87.6490, '$$', 'https://victorygardens.org', ARRAY['new-work', 'drama', 'diverse-voices'], 'Wheelchair accessible, hearing loop available'),
  ('a1000000-0000-0000-0000-000000000008', 'iO Theater', 'io-theater', 'The improv institution. Where long-form improv was born and where generations of comedy legends trained. Classes and shows nightly.', 'school', '1501 N Kingsbury St', 'Old Town', 41.9082, -87.6533, '$', 'https://ioimprov.com', ARRAY['improv', 'comedy', 'sketch'], 'Wheelchair accessible'),
  ('a1000000-0000-0000-0000-000000000009', 'Collaboraction', 'collaboraction', 'Creates "peacebook" productions that explore violence and peace in Chicago. Theater as activism, community engagement as art.', 'storefront', '1579 N Milwaukee Ave', 'Wicker Park', 41.9100, -87.6748, '$', 'https://collaboraction.org', ARRAY['social-justice', 'new-work', 'community'], 'Venue accessibility varies by production'),
  ('a1000000-0000-0000-0000-000000000010', 'Chicago Shakespeare Theater', 'chicago-shakespeare', 'World-class Shakespeare on Navy Pier. Three venues including the intimate Yard theater. Known for bold adaptations and international collaborations.', 'institutional', '800 E Grand Ave', 'Navy Pier', 41.8917, -87.6060, '$$$', 'https://chicagoshakes.com', ARRAY['shakespeare', 'classic', 'musical', 'international'], 'Fully wheelchair accessible, assistive listening, audio description'),
  ('a1000000-0000-0000-0000-000000000011', 'Steep Theatre', 'steep-theatre', 'Fiercely independent storefront known for ambitious productions in an intimate 50-seat space. Punches way above its weight.', 'storefront', '1115 W Berwyn Ave', 'Edgewater', 41.9783, -87.6585, '$', 'https://steeptheatre.com', ARRAY['drama', 'new-work', 'intimate'], 'Ground floor, limited wheelchair seating — call ahead'),
  ('a1000000-0000-0000-0000-000000000012', 'Second City', 'second-city', 'The comedy institution that launched Tina Fey, Bill Murray, and basically everyone. Mainstage revues and improv sets nightly.', 'institutional', '1616 N Wells St', 'Old Town', 41.9112, -87.6347, '$$', 'https://secondcity.com', ARRAY['improv', 'sketch', 'comedy', 'revue'], 'Wheelchair accessible, large print programs available')
INSERT INTO events (id, venue_id, title, slug, description, event_type, genre_tags, start_date, end_date, price_min, price_max, ticket_url, hottix_available) VALUES
  ('b1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001', 'The Roommate', 'the-roommate', 'A Midwestern widow and a woman fleeing her past become unlikely roommates. Jen Silverman''s sharp comedy about reinvention and the lies we tell ourselves.', 'show', ARRAY['comedy', 'drama', 'new-work'], '2026-07-15', '2026-09-07', 30, 98, 'https://steppenwolf.org/tickets', true),
  ('b1000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000002', 'The Infinite Wrench', 'the-infinite-wrench', 'The successor to Too Much Light — 30 plays in 60 minutes. Roll the dice, yell suggestions, and hold on. Every show is different. You pay what you roll plus $9.', 'show', ARRAY['experimental', 'interactive', 'comedy'], '2026-01-01', '2026-12-31', 9, 15, 'https://neofuturists.org/shows', false),
  ('b1000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000003', 'Moby Dick', 'moby-dick', 'Lookingglass does what they do best: turning an impossible novel into jaw-dropping physical theater. Expect aerial work, water, and obsession made flesh.', 'show', ARRAY['adaptation', 'physical-theater', 'spectacle'], '2026-08-01', '2026-10-15', 45, 89, 'https://lookingglasstheatre.org/tickets', true),
  ('b1000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000004', 'Messing with a Friend', 'messing-with-a-friend', 'An original Annoyance musical about a friend group that takes a road trip and discovers they don''t actually like each other. Irreverent, raunchy, and surprisingly heartfelt.', 'show', ARRAY['musical', 'comedy', 'original'], '2026-07-10', '2026-08-30', 15, 20, 'https://theannoyance.com/shows', false),
  ('b1000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000005', 'Antigone', 'antigone', 'Sophocles'' timeless story of conscience vs. authority, reimagined with a contemporary Chicago lens. Court Theatre brings classical weight to urgent modern questions.', 'show', ARRAY['classic', 'drama', 'greek-tragedy'], '2026-09-05', '2026-10-12', 35, 75, 'https://courttheatre.org/tickets', true),
  ('b1000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000006', 'Pilsen Stories', 'pilsen-stories', 'A devised piece by an emerging ensemble exploring gentrification, identity, and home through the voices of Pilsen residents. Raw, local, necessary.', 'show', ARRAY['new-work', 'devised', 'community', 'diverse-voices'], '2026-08-15', '2026-09-14', 20, 30, 'https://thedentheatre.com/shows', false),
  ('b1000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000007', 'How to Defend Yourself', 'how-to-defend-yourself', 'Liliana Padilla''s Pulitzer finalist about a group of sorority sisters who take a self-defense class after an assault on campus. Funny, furious, and essential.', 'show', ARRAY['drama', 'new-work', 'diverse-voices'], '2026-08-22', '2026-09-28', 25, 55, 'https://victorygardens.org/tickets', true),
  ('b1000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000008', 'Long-Form Improv Showcase', 'io-longform-showcase', 'iO''s best house teams perform Harold-format long-form improv. Different teams each night — check the schedule.', 'show', ARRAY['improv', 'comedy'], '2026-01-01', '2026-12-31', 10, 18, 'https://ioimprov.com/shows', false),
  ('b1000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000009', 'Crime Scene Chicago', 'crime-scene-chicago', 'An immersive community production exploring real stories of violence and healing on the South and West sides. Audience becomes witness and participant.', 'show', ARRAY['social-justice', 'immersive', 'community'], '2026-09-01', '2026-09-28', 0, 20, 'https://collaboraction.org/shows', false),
  ('b1000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000010', 'As You Like It', 'as-you-like-it', 'Shakespeare''s joyful comedy of disguise, love, and forest exile — set in a neon-lit Chicago nightclub. Gender-fluid casting and a live DJ.', 'show', ARRAY['shakespeare', 'comedy', 'adaptation'], '2026-08-10', '2026-10-05', 40, 95, 'https://chicagoshakes.com/tickets', true),
  ('b1000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000011', 'The Wolves', 'the-wolves', 'Sarah DeLappe''s Pulitzer finalist about a girls'' indoor soccer team warming up before games. Overlapping dialogue, fierce energy, quiet devastation.', 'show', ARRAY['drama', 'new-work', 'intimate'], '2026-08-07', '2026-09-13', 15, 28, 'https://steeptheatre.com/shows', false),
  ('b1000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000012', 'The Second City Revue: We''re All In This Room Together', 'second-city-revue-2026', 'The legendary mainstage revue. Sketch comedy and improv tackling everything from politics to dating apps. A Chicago rite of passage.', 'show', ARRAY['sketch', 'improv', 'comedy', 'revue'], '2026-06-01', '2026-12-31', 30, 65, 'https://secondcity.com/shows', true),
